import {expect} from '@playwright/test';
export async function exercisePhotoFlags(page,{lang,photos,getPhoto,failNext,error,screenshot}){
  const text=(zh,en)=>lang==='en'?en:zh,[a,b,c]=photos,card=p=>page.locator(`.photo-card[data-photo-id="${p.id}"]`),select=p=>card(p).locator('.select-box');
  await expect(card(a)).toBeVisible();await select(a).click();
  if(failNext){const settled=await failNext();await page.keyboard.press('Shift+p');await expect(page.locator('.toast')).toContainText(error);if(settled)await settled();expect((await getPhoto(a.id)).flag).toBe('unmarked');await expect(card(a)).toHaveClass(/selected/);await expect(card(b)).not.toHaveClass(/selected/);}
  let idReads=0;const record=request=>{if(new URL(request.url()).pathname==='/api/photos/ids')idReads++;};page.on('request',record);
  for(const [key,value] of [['p','picked'],['x','rejected'],['u','unmarked']]){await page.keyboard.press(key);await expect.poll(async()=>(await getPhoto(a.id)).flag).toBe(value);}
  await page.keyboard.press('Shift+p');await expect.poll(async()=>(await getPhoto(a.id)).flag).toBe('picked');await expect(card(b)).toHaveClass(/selected/);await expect(card(a)).not.toHaveClass(/selected/);await expect(card(b).locator('.photo-image')).toBeFocused();
  await page.keyboard.press('Shift+x');await expect.poll(async()=>(await getPhoto(b.id)).flag).toBe('rejected');await expect(card(c)).toHaveClass(/selected/);
  await page.keyboard.press('Shift+u');await expect.poll(async()=>(await getPhoto(c.id)).flag).toBe('unmarked');await expect(card(c)).toHaveClass(/selected/);
  page.off('request',record);expect(idReads).toBe(0);
  const keep=await getPhoto(a.id);expect(keep).toMatchObject({rating:0,rating_source:'manual',favorite:true,color_label:'blue',tags:['manual']});
  await select(a).click();await page.keyboard.press('x');await expect.poll(async()=>Promise.all([a,c].map(async p=>(await getPhoto(p.id)).flag))).toEqual(['rejected','rejected']);
  await page.getByRole('button',{name:text('批量编辑','Batch Edit'),exact:true}).click();const batch=page.getByRole('dialog');await batch.getByRole('combobox',{name:text('选片标记','Culling flag'),exact:true}).selectOption('picked');await batch.getByRole('button',{name:text('保存','Save'),exact:true}).click();await expect(batch).toHaveCount(0);await expect.poll(async()=>Promise.all([a,c].map(async p=>(await getPhoto(p.id)).flag))).toEqual(['picked','picked']);
  await page.getByRole('button',{name:text('筛选','Filter'),exact:true}).click();const filter=page.locator('[data-facet=flag]');await filter.click();await page.locator('.facet-popover').getByRole('checkbox',{name:new RegExp('^'+text('留用','Picked'))}).check();await page.locator('.facet-popover').getByRole('button',{name:text('关闭筛选','Close filter'),exact:true}).click();await expect(page.locator('.photo-card')).toHaveCount(2);
  await card(a).locator('.photo-image').dblclick();await expect(page.locator('.photo-viewer')).toBeVisible();await page.keyboard.press('Shift+x');await expect.poll(async()=>(await getPhoto(a.id)).flag).toBe('rejected');await expect(page.locator('.viewer-caption b')).toHaveText(c.file_name);
  await page.keyboard.press('u');await expect.poll(async()=>(await getPhoto(c.id)).flag).toBe('unmarked');await expect(page.locator('.photo-viewer')).toHaveCount(0);await expect(page.locator('.photo-card')).toHaveCount(0);
  await filter.click();await page.locator('.facet-popover').getByRole('button',{name:text('清除此项','Clear this filter'),exact:true}).click();await expect(page.locator('.photo-card')).toHaveCount(3);await card(b).locator('.photo-image').dblclick();const viewer=page.locator('.photo-viewer');await viewer.getByRole('button',{name:text('照片信息','Photo information'),exact:true}).click();const tags=viewer.locator('.tag-editor input');await tags.fill('typing');await tags.press('p');await tags.press('Shift+X');expect((await getPhoto(b.id)).flag).toBe('rejected');await expect(tags).toHaveValue('typingpX');
  if(screenshot)await page.screenshot({path:screenshot,fullPage:true});await page.keyboard.press('Escape');await page.reload();await expect(card(a)).toBeVisible();expect((await getPhoto(a.id)).flag).toBe('rejected');expect((await getPhoto(c.id)).flag).toBe('unmarked');
  await page.locator('.workspace-subnav').getByRole('button',{name:text('影集','Albums'),exact:true}).click();await page.getByRole('button',{name:text('新建条件集合','New rule collection'),exact:true}).click();const rule=page.getByRole('dialog'),ruleName='Culling rule '+a.id;await rule.getByRole('textbox',{name:text('影集名称','Album Name'),exact:true}).fill(ruleName);const leaf=rule.locator('.query-leaf').first();await leaf.getByRole('combobox',{name:text('照片字段','Photo field'),exact:true}).selectOption('flag');await leaf.getByRole('combobox',{name:text('条件值','Condition value'),exact:true}).selectOption('rejected');await expect(rule.getByText(text('匹配 2 次拍摄','2 matching captures'),{exact:true})).toBeVisible();await rule.getByRole('button',{name:text('保存条件集合','Save rule collection'),exact:true}).click();await expect(rule).toHaveCount(0);await page.locator('.album-card').filter({has:page.getByRole('heading',{name:ruleName,exact:true})}).locator('.album-cover').click();await expect(page.locator('.photo-card')).toHaveCount(2);await card(b).locator('.photo-image').dblclick();await expect(page.locator('.photo-viewer')).toBeVisible();await page.keyboard.press('u');await expect.poll(async()=>(await getPhoto(b.id)).flag).toBe('unmarked');await expect(page.locator('.photo-viewer')).toHaveCount(0);await expect(page.locator('.photo-card')).toHaveCount(1);
}
